import { useMemo } from "react";
import { marked } from "marked";
import { BarChart3 } from "lucide-react";
import { useApi } from "../api";
import { Card, Empty, PageHead, Spinner } from "../components/ui";

type R = { markdown: string | null; suite: { splits?: Record<string, { episodes?: number; by_family?: Record<string, number> }> } & Record<string, unknown> | null };

export default function Results() {
  const { data } = useApi<R>("/results");
  // docs/results.md is generated by eval/report.py from our own runs: trusted repo content
  const html = useMemo(() => (data?.markdown ? (marked.parse(data.markdown, { async: false }) as string) : ""), [data]);
  return (
    <div className="page stack" style={{ gap: 18 }}>
      <PageHead title="Evaluation results" sub="Attack success, false-refusal and cost across the five protection levels (eval/report.py)." />
      {!data ? <Spinner /> : html ? <Card><div className="md" dangerouslySetInnerHTML={{ __html: html }} /></Card>
        : <Card><Empty icon={<BarChart3 />} title="No results yet">Run <code>make eval-local</code>, then <code>python -m eval.report</code> to generate docs/results.md.</Empty></Card>}
      {data?.suite && <Card title="Attack suite manifest" sub="docs/results/suite_manifest.json"><pre className="mono small" style={{ margin: 0, overflowX: "auto" }}>{JSON.stringify(data.suite, null, 2)}</pre></Card>}
    </div>
  );
}
